-- ═════════════════════════════════════════════════════════════
-- Vote2027 — calendrier du "Vote du jour" (1 question planifiée par jour)
-- À exécuter après supabase/vote_bank_schema.sql. Idempotent.
--
-- Source : tableur « vote-du-jour (2) » (218 questions, 16/10/2026 → 21/05/2027).
-- Chaque question planifiée porte sa date de publication ; get_daily_vote_question
-- renvoie la question du jour. Les 20 questions V001–V020 de la banque restent
-- comme question de repli si aucune question n'est planifiée un jour donné.
-- ═════════════════════════════════════════════════════════════

alter table public.vote_questions add column if not exists date_publication date unique;
alter table public.vote_questions add column if not exists theme text;
-- Les questions planifiées n'ont pas de sous-texte Oui / Non.
alter table public.vote_questions alter column oui_label drop not null;
alter table public.vote_questions alter column non_label drop not null;

on conflict (code) do update set
  ordre = excluded.ordre,
  question = excluded.question,
  theme = excluded.theme,
  date_publication = excluded.date_publication,
  statut = excluded.statut;

create or replace function public.get_daily_vote_question(p_date date default (now() at time zone 'Europe/Paris')::date)
returns table (
  code text,
  question text,
  oui_label text,
  non_label text
)
language sql
stable
security definer set search_path = public
as $$
  select v.code, v.question, v.oui_label, v.non_label
  from public.vote_questions v
  where v.statut = 'active'
    and (v.date_publication = p_date
         or (v.date_publication is null
             and not exists (select 1 from public.vote_questions s
                              where s.statut = 'active' and s.date_publication = p_date)))
  order by (v.date_publication is null), md5(v.code || p_date::text)
  limit 1;
$$;

grant execute on function public.get_daily_vote_question(date) to authenticated, anon;
